-- Complete first-pass editorial content for Filosofia da Educação.
-- Source basis: Severino (2006) and Back (2019), with content kept as draft.
WITH seed(discipline_name,topic_name,position,title,content) AS (VALUES ('Filosofia da Educação','O que é filosofia da educação',1,'Conceito central','A Filosofia da Educação toma a educação como problema de reflexão: pergunta por seus sentidos, fundamentos, finalidades, pressupostos e consequências. Não é apenas um catálogo de teorias pedagógicas; investiga filosoficamente a própria experiência educativa.'),
('Filosofia da Educação','O que é filosofia da educação',2,'A pergunta filosófica','Perguntas filosóficas não procuram apenas uma definição rápida. Elas problematizam aquilo que parece óbvio: o que é formar alguém, que conhecimento merece ser ensinado, qual é o papel do professor e que finalidade a escola assume.'),
('Filosofia da Educação','O que é filosofia da educação',3,'Educação como formação humana','Severino analisa a educação como processo de formação humana e mostra que as concepções de formação mudam historicamente. Essa mudança altera também a maneira de compreender a finalidade da educação.'),
('Filosofia da Educação','O que é filosofia da educação',4,'Exemplo para visualizar','Compare duas respostas à pergunta “para que educar?”. Uma pode enfatizar preparação para a vida social; outra, desenvolvimento cultural e formação humana. A diferença envolve concepções sobre pessoa e sociedade.'),
('Filosofia da Educação','O que é filosofia da educação',5,'Situação para analisar','Uma escola decide reformular suas práticas, mas não explicita que ideia de formação orientará as escolhas. O problema filosófico é identificar os pressupostos já presentes, mesmo quando não foram declarados.'),
('Filosofia da Educação','O que é filosofia da educação',6,'Erro comum','Reduzir Filosofia da Educação a decorar nomes de filósofos e resumos de suas ideias. O estudo filosófico exige reconstruir perguntas, argumentos, conceitos e consequências.'),
('Filosofia da Educação','O que é filosofia da educação',7,'Aprofundamento','A Filosofia da Educação pode funcionar como esforço de interpretação da prática educacional em condições históricas e culturais concretas. Severino destaca esse papel ao discutir o sentido atual da formação humana.'),
('Filosofia da Educação','O que é filosofia da educação',8,'Aplicação na formação','Ao analisar uma prática pedagógica, identifique a concepção de pessoa, conhecimento, sociedade e educação que a sustenta. Depois pergunte quais consequências essa concepção produz.'),
('Filosofia da Educação','O que é filosofia da educação',9,'Síntese','Filosofia da Educação é reflexão crítica sobre a educação enquanto problema humano, cultural e histórico. Seu valor está em tornar visíveis fundamentos e pressupostos que orientam práticas.'),
('Filosofia da Educação','O que é filosofia da educação',10,'Para revisar','Explique por que perguntar “para que educar?” é uma pergunta filosófica. Em seguida, relacione sua resposta a uma situação concreta de escola.'),
('Filosofia da Educação','Educação e conhecimento',1,'Conceito central','A relação entre educação e conhecimento envolve perguntas sobre o que conhecer, como justificar conhecimentos, como eles são transmitidos e como participam da formação humana.'),
('Filosofia da Educação','Educação e conhecimento',2,'Conhecimento não é só informação','Ensinar não é transferir informação de modo mecânico. Conhecimento envolve compreensão, relações, linguagem, investigação, interpretação e possibilidade de justificar afirmações.'),
('Filosofia da Educação','Educação e conhecimento',3,'Formação cultural','Para Severino, a educação contemporânea pode ser compreendida como formação cultural, sem abandonar as dimensões ética e política. Isso amplia a discussão sobre o que significa conhecer e formar-se.'),
('Filosofia da Educação','Educação e conhecimento',4,'Exemplo para visualizar','Saber a definição de “currículo” é diferente de conseguir analisar um currículo, reconhecer escolhas feitas e justificar uma interpretação. O segundo caso mobiliza conhecimento de forma mais complexa.'),
('Filosofia da Educação','Educação e conhecimento',5,'Situação para analisar','Um estudante memoriza conceitos para uma prova, mas não consegue usá-los em um caso. O problema pode estar na relação entre reprodução de informação e compreensão conceitual.'),
('Filosofia da Educação','Educação e conhecimento',6,'Erro comum','Tratar todo conteúdo escrito ou toda afirmação encontrada na internet como conhecimento suficientemente validado para fins acadêmicos.'),
('Filosofia da Educação','Educação e conhecimento',7,'Aprofundamento','A Filosofia da Educação permite perguntar como critérios de verdade, relevância, linguagem e experiência entram no processo educativo. Em vez de aceitar o conhecimento como dado, investiga seus pressupostos.'),
('Filosofia da Educação','Educação e conhecimento',8,'Aplicação na formação','Ao estudar uma disciplina, diferencie informação, explicação, argumento e evidência. Essa distinção melhora tanto o estudo do aluno quanto a futura prática docente.'),
('Filosofia da Educação','Educação e conhecimento',9,'Síntese','Educar para o conhecimento significa criar condições para compreender, questionar, relacionar e usar conhecimentos de forma responsável e contextualizada.'),
('Filosofia da Educação','Educação e conhecimento',10,'Para revisar','Pegue um conceito que você memorizou recentemente e explique como demonstraria que realmente o compreendeu.'),
('Filosofia da Educação','Ética e formação humana',1,'Conceito central','A dimensão ética da educação aparece quando o ato educativo envolve valores, responsabilidade, relação com o outro, liberdade, limites e decisões sobre o que merece ser promovido ou evitado.'),
('Filosofia da Educação','Ética e formação humana',2,'Ética não é apenas regra','Ensinar ética não se resume a apresentar regras de comportamento. É necessário discutir razões, consequências, conflitos de valores e responsabilidade pelas escolhas.'),
('Filosofia da Educação','Ética e formação humana',3,'Dimensão ética da formação','Severino destaca a dimensão ética entre os fundamentos históricos da compreensão da educação e discute como ela permanece articulada à formação humana.'),
('Filosofia da Educação','Ética e formação humana',4,'Exemplo para visualizar','Uma professora decide interromper uma atividade para lidar com uma situação de humilhação entre estudantes. A decisão envolve mais que gestão de sala: implica uma concepção sobre respeito, dignidade e convivência.'),
('Filosofia da Educação','Ética e formação humana',5,'Situação para analisar','Dois valores entram em tensão em um caso escolar. Em vez de escolher rapidamente um lado, identifique os valores envolvidos, as pessoas afetadas e as razões que podem sustentar cada decisão.'),
('Filosofia da Educação','Ética e formação humana',6,'Erro comum','Confundir ética com obediência automática ou com opinião pessoal. Uma análise ética exige justificar a decisão e considerar seus efeitos sobre os envolvidos.'),
('Filosofia da Educação','Ética e formação humana',7,'Aprofundamento','A formação humana é inseparável de escolhas sobre modos de convivência e responsabilidade. Em Severino, a discussão ética está ligada à compreensão mais ampla da educabilidade humana.'),
('Filosofia da Educação','Ética e formação humana',8,'Aplicação na formação','Ao observar uma prática educativa, pergunte como a atividade trata autonomia, respeito, diferença, responsabilidade e participação dos estudantes.'),
('Filosofia da Educação','Ética e formação humana',9,'Síntese','A educação possui dimensão ética porque forma pessoas em relações concretas. O trabalho pedagógico sempre envolve escolhas que podem ser examinadas e justificadas.'),
('Filosofia da Educação','Ética e formação humana',10,'Para revisar','Descreva um dilema ético possível na escola e mostre quais valores e responsabilidades entram em conflito.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',1,'Conceito central','Correntes filosóficas oferecem modos diferentes de compreender conhecimento, pessoa, liberdade, autoridade, experiência e formação. Estudá-las significa comparar problemas e argumentos, não memorizar etiquetas.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',2,'Como comparar correntes','Uma comparação útil identifica: visão de ser humano, concepção de conhecimento, finalidade da educação, papel do professor, papel do estudante e relação com a sociedade.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',3,'Perspectiva histórica','Severino mostra que concepções de formação humana mudaram ao longo da tradição filosófica: diferentes períodos destacaram de modos distintos dimensões ética, política e cultural.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',4,'Exemplo para visualizar','Duas propostas podem defender “autonomia”, mas atribuir sentidos diferentes ao termo. Comparar o conceito dentro de cada perspectiva evita concluir que palavras iguais significam a mesma coisa.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',5,'Situação para analisar','Uma atividade pedagógica privilegia transmissão, outra enfatiza investigação. Em vez de declarar uma superioridade automática, pergunte quais concepções de conhecimento e aprendizagem estão por trás de cada proposta.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',6,'Erro comum','Criar caricaturas: “uma corrente é só decorar” e “outra é só deixar o aluno livre”. Correntes complexas não podem ser reduzidas a slogans.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',7,'Aprofundamento','A Filosofia da Educação ganha força quando as correntes são estudadas como respostas a problemas históricos concretos. O foco passa do rótulo para o argumento e suas implicações.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',8,'Aplicação na formação','Quando encontrar uma teoria pedagógica, procure identificar quais pressupostos filosóficos sobre pessoa, conhecimento e sociedade ela mobiliza.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',9,'Síntese','Conhecer correntes filosóficas é ampliar o repertório para analisar práticas e argumentos. A comparação deve revelar diferenças reais de pressupostos, finalidades e consequências.'),
('Filosofia da Educação','Principais correntes filosóficas da educação',10,'Para revisar','Monte uma tabela própria com duas correntes estudadas, comparando ser humano, conhecimento, educação, professor e estudante.'),
('Filosofia da Educação','Problemas contemporâneos da educação',1,'Conceito central','Problemas contemporâneos da educação exigem análise de questões como tecnologia, desigualdade, pluralidade cultural, autonomia, sentido da escola e transformação das formas de produzir conhecimento.'),
('Filosofia da Educação','Problemas contemporâneos da educação',2,'Por que problematizar','Uma questão contemporânea não se resolve apenas identificando uma ferramenta ou uma opinião. É necessário explicitar conceitos, valores, consequências e condições históricas.'),
('Filosofia da Educação','Problemas contemporâneos da educação',3,'Mudanças histórico-culturais','Severino argumenta que mudanças nas condições histórico-culturais colocam novos desafios às referências filosóficas da educação e recolocam a pergunta sobre seu sentido.'),
('Filosofia da Educação','Problemas contemporâneos da educação',4,'Exemplo para visualizar','A entrada de inteligência artificial na escola pode ser discutida como problema filosófico: o que significa aprender quando uma ferramenta produz respostas? O que deve continuar sendo autoria humana?'),
('Filosofia da Educação','Problemas contemporâneos da educação',5,'Situação para analisar','Uma instituição adota tecnologia educacional sem discutir seus objetivos formativos. Analise quais concepções de aprendizagem, conhecimento e estudante ficam implícitas na decisão.'),
('Filosofia da Educação','Problemas contemporâneos da educação',6,'Erro comum','Tratar toda novidade tecnológica como progresso ou toda mudança como ameaça. A análise filosófica procura os pressupostos e as consequências de cada posição.'),
('Filosofia da Educação','Problemas contemporâneos da educação',7,'Aprofundamento','A discussão contemporânea pode recolocar antigas perguntas em novas condições. Questões sobre autonomia, cultura, ética e formação continuam presentes, ainda que os contextos mudem.'),
('Filosofia da Educação','Problemas contemporâneos da educação',8,'Aplicação na formação','Ao analisar uma tendência educacional atual, formule três perguntas: que problema ela tenta resolver? Que concepção de educação pressupõe? Que consequências pode produzir?'),
('Filosofia da Educação','Problemas contemporâneos da educação',9,'Síntese','Pensar os problemas contemporâneos da educação é interpretar mudanças atuais sem abandonar perguntas fundamentais sobre formação humana, conhecimento, ética e vida coletiva.'),
('Filosofia da Educação','Problemas contemporâneos da educação',10,'Para revisar','Escolha uma questão educacional contemporânea e escreva uma pergunta filosófica que permita analisá-la além de opiniões imediatas.'))
UPDATE public.material_sections ms
SET title=s.title,content=s.content,section_type=CASE s.position
 WHEN 1 THEN 'concept' WHEN 2 THEN 'explanation' WHEN 3 THEN 'explanation'
 WHEN 4 THEN 'examples' WHEN 5 THEN 'examples' WHEN 6 THEN 'common_mistakes'
 WHEN 7 THEN 'deepening' WHEN 8 THEN 'deepening' WHEN 9 THEN 'review' ELSE 'review' END
FROM seed s,public.materials m,public.topics t,public.disciplines d
WHERE ms.material_id=m.id AND m.topic_id=t.id AND t.discipline_id=d.id
AND d.name=s.discipline_name AND t.name=s.topic_name AND ms.position=s.position;

update public.disciplines
set curriculum_status='in_progress'
where name='Filosofia da Educação'
and course_id=(select id from public.courses where slug='pedagogia' limit 1);